%   Vincentas Gerdvilis
%   Ef-25/1
%   2026-09-10

clear
close all
[X Y] = meshgrid(-2:0.1:1);
f = 1 - 2.*X.^2 - 3.*Y.^2;
surf(f) %[output:5fc6c672]
colormap summer %[output:5fc6c672]
view(70, 70) %[output:5fc6c672]
xlabel('X') %[output:5fc6c672]
ylabel('Y') %[output:5fc6c672]
zlabel('Z') %[output:5fc6c672]
title('f(x, y) = 1 - 2x^2 - 3y^2') %[output:5fc6c672]
shading flat %[output:5fc6c672]
%%
clear
close all
[X Y] = meshgrid(-2:0.1:2);
f = sin((abs(X + Y))./(20)).*exp(-abs(X + Y));
surf(f); %[output:9da685b1]
shading flat %[output:9da685b1]
colormap summer %[output:9da685b1]
view(10, 10) %[output:9da685b1]
xlabel('X') %[output:9da685b1]
ylabel('Y') %[output:9da685b1]
zlabel('Z') %[output:9da685b1]
title('f(x, y)') %[output:9da685b1]

